function Player2DBadgePanel:_RefreshAllBadges()

    KTool.DestroyGameObjectChildren(self.BadgeShowRoot.gameObject, false)

    self.badgeIdList = {}
    self.badgeMap = {}

    self.ownedBadge   = PlayerInfoUtils.GetItemHasByKind(Constants.PlayerAvatarItemType.Paster)
    self.unlockedBadgeIdList  = table.keys(self.ownedBadge) -- 已到手(已解锁) 的徽章 ids, string "6200018" 这种值
    -- string -> int
    for i=1,#self.unlockedBadgeIdList do 
        self.unlockedBadgeIdList[i] = checkInt( self.unlockedBadgeIdList[i] )
    end

    ---
    -- local allBadgeIdList = {} -- 配表中全体 徽章 ids, int
    -- local vos = CfUtils.GetCf(AutoIds.IdSetting952, "PlayHeadAvatarVo", true)
    -- for  k,vo in pairs(vos) do 
    --     if vo.kind == 3 then
    --         table.insert( allBadgeIdList, vo.id )
    --     end 
    -- end 
    local allBadgeIdList = PlayerInfoUtils.GetItemIdsByKind(Constants.PlayerAvatarItemType.Paster) -- 配表中全体 徽章 ids, type = string

    
    -- 整理排序: 已经获得的排前面, 再按 id 大小排
    table.sort(self.unlockedBadgeIdList, function(IdA, IdB)
        return IdA < IdB
    end)
    -- table.sort(allBadgeIdList, function(IdA, IdB)
    --     return IdA < IdB
    -- end)
    --  
    
    for k,id in pairs(self.unlockedBadgeIdList) do 
        table.insert( self.badgeIdList, id )
        self:_AddToBadgeMap( id, Player2DStates.BadgeState.UnShow )
    end 
    for k,idStr in pairs(allBadgeIdList) do 
        local idInt = tonumber(idStr)
        if table.indexof( self.unlockedBadgeIdList, idInt ) == false then 
            table.insert( self.badgeIdList, idInt )
            self:_AddToBadgeMap( idInt, Player2DStates.BadgeState.Locked )
        end
    end

    -- 正在展示的 徽章数据
    local badgeShowMap = self.mainDialog:GetBadgeShowMap()  -- 正在展示的 徽章信息 {k:badgeId, v:{ pos = {0,0} } }
    for badgeId,v in pairs(badgeShowMap) do  
        local id = checkInt(badgeId)
        if type(self.badgeMap[id]) ~= "table" then 
            printError( "koko - 数据异常" )
            return
        end 
        self.badgeMap[id].state = Player2DStates.BadgeState.Showed
        self.badgeMap[id].pos = Vector2( tonumber(v.pos[1]), tonumber(v.pos[2]) )
    end

    --- 绘制 左侧 绘制列表:
    local totalNum = #self.badgeIdList
    if not self.BadgeList.IsListViewInit then
        self.BadgeList:InitGridView(totalNum, Bind(self, self.OnGetBadgeCell))
    else
        GameUtils.ReloadData(self.BadgeList, totalNum)
    end

    --- 绘制 右侧 可展示徽章: 
    for idx,id in pairs(self.badgeIdList) do 
        if self:IsShowedBadge( id ) then 
            self:_DrawShowedBadge( idx, id, self.badgeMap[id].pos )
        end
    end 

    -- 初始时, 不指向任何元素:
    self:SetSelectedIndex( -1 )
end


function Player2DBadgePanel:_AddToBadgeMap( badgeId_, state_ )
    local id = checkInt(badgeId_)
    local pos2 = Vector2( 0.0, 0.0 )
    local size2 = Vector2( 240.0, 240.0 )
    self.badgeMap[id] = { state = state_, rawPos = pos2, pos = pos2, size = size2, isCollect = false, transform = nil, luaEnv = nil }
end


function Player2DBadgePanel:RemoveBadge( badgeId_ )
    self:_RefreshAllBadges()
end


function Player2DBadgePanel:_DrawShowedBadge( badgeIdx_, badgeId_, pos2_ )

    local newgo = CfUtils.InstantiateGo(self.BadgeCell.gameObject, self.BadgeShowRoot)
    local entityLuaEnv = CfUtils.GetLuaScr(newgo, "Game.UI.Player.Player2DBadgeMovableEntity") 
    assert( isNotNull(entityLuaEnv) ) 
    self.badgeMap[badgeId_].luaEnv = entityLuaEnv
    self.badgeMap[badgeId_].transform = newgo.transform
    self.badgeMap[badgeId_].transform.anchoredPosition = pos2_
    self.badgeMap[badgeId_].pos = pos2_

    ---@type GoodsVo
    local itemConf = self:GetBadgeConfById(badgeId_)
    entityLuaEnv:Init( badgeId_, itemConf.photoPath )


    SetButtonAction(newgo, function()

        local badgeData = self.badgeMap[badgeId_]
        if self:IsInEditMode() then 

            print("点击 可动 徽章 " .. tostring(badgeId_) .. ": pos: " .. badgeData.pos:ToString() .. "; tfPos: " 
            .. self.badgeMap[badgeId_].transform.anchoredPosition:ToString() )

            self:_FloatUp2TopOrder( badgeData.transform ) -- 将本徽章 上浮到最上层
            self:SetSelectedIndex( badgeIdx_ )

            badgeData.luaEnv:ShowFrame({ isShow = self:IsInEditMode(), isRed = badgeData.isCollect, isEdit = true }) -- 强制绘制 绘制边框

        else
            self:_DrawTipPopup( badgeId_, badgeData.transform.gameObject, true )
        end
        
    end)


    SetButtonAction(entityLuaEnv.BtnCancel, function()
        print("点击 可动 徽章 删除键" .. tostring(badgeId_) )

        if isNotNull(self.badgeMap[badgeId_].transform) then 
            Object.Destroy( self.badgeMap[badgeId_].transform.gameObject )
        end 
        self.badgeMap[badgeId_].transform = nil
        self.badgeMap[badgeId_].luaEnv = nil
        self.badgeMap[badgeId_].state = Player2DStates.BadgeState.UnShow

        -- 重置 idx: 
        -- 要么红框选中一个 还在碰撞态的徽章 并将其置顶,  要么 idx 置空
        local lastColloectBadgeId = self:_DoShowedBadgesCollect()
        local lastColloectBadgeIdx = self:GetBadgeIndexById( lastColloectBadgeId ) -- 可能且允许为 -1
        self:SetSelectedIndex( lastColloectBadgeIdx )

        -- 将最后一个 碰撞态的 右侧徽章 置顶
        if lastColloectBadgeIdx >= 1 then
            self:_FloatUp2TopOrder( self.badgeMap[lastColloectBadgeId].transform )
        end

        GameUtils.ReloadData(self.BadgeList, #self.badgeIdList) -- 重绘 左侧绘制列表
    end)

    SetButtonAction(entityLuaEnv.BtnSave, function()
        print("点击 可动 徽章 确认键" .. tostring(badgeId_) )
        if self.badgeMap[badgeId_].isCollect then 
            GameUtils.Toast( localize("无法放下徽章") ) -- 飘字
            return 
        end

        -- 删除 蓝框
        self.badgeMap[badgeId_].luaEnv:ShowFrame({ isShow = false, isRed = false, isEdit = false })
    end)
end


-- 让徽章置顶
function Player2DBadgePanel:_FloatUp2TopOrder( tf_ )
    local childNum = tf_.parent.childCount
    tf_:SetSiblingIndex( childNum-1 )
end


-- =========================== 徽章 碰撞检测 ==================================

-- 做全体 可动徽章碰撞检测
-- todo: 暂为 最简方案,  未来添加优化
function Player2DBadgePanel:_DoShowedBadgesCollect()
    --- 清空 flags:
    -- for id,v in pairs(self.badgeMap) do
    --     if v.state == Player2DStates.BadgeState.Showed then 
    --         v.isFindCollection = false
    --     end 
    -- end
    ---
    local lastColloectBadgeId = -1
    for id,v in pairs(self.badgeMap) do
        if v.state == Player2DStates.BadgeState.Showed then 
            local isCollect = self:_IsShowedBadgeCollectedWithOth(id)

            v.luaEnv:ShowFrame({ isShow = isCollect and self:IsInEditMode(), isRed = isCollect, isEdit = (self:GetSelectedBadgeId()==id) })
            v.isCollect = isCollect
            if isCollect then 
                lastColloectBadgeId = id
            end 
        end
    end
    return lastColloectBadgeId
end



function Player2DBadgePanel:_IsAnyShowedBadgeCollect()
    for id,v in pairs(self.badgeMap) do
        if v.state == Player2DStates.BadgeState.Showed and v.isCollect == true then 
            return true
        end
    end
    return false
end



function Player2DBadgePanel:_IsShowedBadgeCollectedWithOth( badgeId_ )
    for id,v in pairs(self.badgeMap) do
        if id~=badgeId_ and v.state == Player2DStates.BadgeState.Showed then 
            if self:_IsTwoBadgesCollect( badgeId_, id ) then 
                return true
            end
        end
    end
    return false
end


---@return boolean
function Player2DBadgePanel:_IsTwoBadgesCollect( aId_, bId_ )
    local a = self.badgeMap[aId_]
    local b = self.badgeMap[bId_]
    local aBounds = Bounds( Vector3( a.pos.x, a.pos.y, 0 ), Vector3( a.size.x, a.size.y, 1 ) )
    local bBounds = Bounds( Vector3( b.pos.x, b.pos.y, 0 ), Vector3( b.size.x, b.size.y, 1 ) )

    if isNull(aBounds) or isNull(bBounds) then 
        printError("koko - 异常, 没找到 bounds")
        return false
    end 
    return aBounds:Intersects( bBounds )
end



