function Player2DBadgePanel:SetSelectedBadgeId(newIdx, oldIdx)

    local isSelectSomeOne = (newIdx>=1)
    local oldItemId = self:GetSelectedBadgeId() -- cache

    -- 若 newIdx == -1, 表示不指向任何 徽章
    if isSelectSomeOne then
        self.selectedBadgeId_ = checkInt(self.badgeIdList[newIdx])
    else
        self.selectedBadgeId_ = -1
    end
    
    -- 没修改指向, 啥也不用动:
    if oldItemId == self:GetSelectedBadgeId() then
        return
    end

    if oldIdx>=1 then
        -- 刷新绘制 左区列表元素:
        local cell = self.BadgeList:GetShownItemByItemIndex(oldIdx - 1)
        ---@type Player2DBadgePanelBadgeNode
        local cellEnv = CfUtils.GetLuaScr(cell, BadgeListNodePath)
        if cellEnv then
            cellEnv:UpdateSelectStatus(false)
        else 
            printError("koko - 没找到 ImgSelect 节点")
        end

        -- 刷新绘制 右区展示元素:
        if self:IsShowedBadge(self.badgeIdList[oldIdx]) then 
            local badgeData = self.badgeMap[self.badgeIdList[oldIdx]]
            badgeData.luaEnv:ShowFrame({ isShow = badgeData.isCollect and self:IsInEditMode(), isRed = badgeData.isCollect, isEdit = false })
        end 
        
    end

    if isSelectSomeOne then
        -- 刷新绘制 左区列表元素:
        local newCell = self.BadgeList:GetShownItemByItemIndex(newIdx - 1)
        ---@type Player2DBadgePanelBadgeNode
        local newCellEnv = CfUtils.GetLuaScr(newCell, BadgeListNodePath)
        if newCellEnv then
            newCellEnv:UpdateSelectStatus(true)
        else 
            printError("koko - 没找到 ImgSelect 节点")
        end
    
        -- update "New"  如果选中的这个 原本是 "New", 那么现在要消除它的 "New" 状态
        local newBadgeId = self:GetSelectedBadgeId()
        if PlayerInfoUtils.CheckAvatarIsNew(newBadgeId) then
            PlayerInfoUtils.UpdateAvatarNewStateById(newBadgeId, false)
            if newCellEnv then
                newCellEnv:UpdateNewMark()
            end
        end

        -- 刷新绘制 右区展示元素:
        if self:IsShowedBadge(self.badgeIdList[newIdx]) then 
            local badgeData = self.badgeMap[self.badgeIdList[newIdx]]
            badgeData.luaEnv:ShowFrame({ isShow = self:IsInEditMode(), isRed = badgeData.isCollect, isEdit = true })
        end
    end
end


