-- 存储所有正在被展示的 徽章
function Player2DBadgePanel:WhenClickBtn_Save()
    print("koko - Player2DBadgePanel:WhenClickBtn_Save")
    if self:_IsAnyShowedBadgeCollect() then 
        GameUtils.Toast( localize("无法保存") ) -- 飘字
        return
    end 

    -- =========== 存储 右侧展示区数据: ===============
    local badgeShowMap = {}
    for id,v in pairs(self.badgeMap) do 
        if v.state == Player2DStates.BadgeState.Showed then
            --badgeShowMap[tostring(id)] = {pos = { checkInt(v.pos.x),  checkInt(v.pos.y) } }
            badgeShowMap[tostring(id)] = {pos = { checkNumber(v.pos.x),  checkNumber(v.pos.y) } }
        end
    end 
    local medalsJsonData = table.serialize(badgeShowMap)
    --printError( "存档:\n" .. medalsJsonData )

    GameUtils.Request(Interfaces.PlayerSetMedals, {medals = medalsJsonData}, function(request, response)
        if checkInt(response.errCode) == 0 then

            -- 改写本地数据:  右侧徽章区数据
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            playerComponent.playerDojo.medals = badgeShowMap

            self:_RefreshAllBadges()
            self.mainDialog:OnClickBtn_badgeExitBtn() -- 即时退出
            GameUtils.Toast( localize("保存成功") ) -- 飘字
        end
    end)
end 





