function Player2DBadgePanel:OnGetBadgeCell(listView, index0Based)
    if index0Based < 0 then return end
    local cell = listView:NewListViewItem(BadgeListNodeName)
    self:RefreshItemCell(cell, index0Based+1)
    return cell
end

-- 绘制一个 左侧列表中的徽章
function Player2DBadgePanel:RefreshItemCell(node, index1Based)
    local badgeId = checkInt(self:GetBadgeIdByIndex(index1Based))
    ---@type Player2DBadgePanelBadgeNode
    local cellEnv = CfUtils.GetLuaScr(node, BadgeListNodePath)
    cellEnv:SetLuaIndex(index1Based)
    cellEnv:SetCellData({
        badgeId  = badgeId,
        isShowed = self:IsShowedBadge(badgeId),
        isSelect = badgeId == self:GetSelectedBadgeId(),
        isLocked = self:IsLockedBadge(badgeId),
        isMySelf = self:IsShowMySelf(),
    })
    
    cellEnv:SetClickBadgeCB(function(clickIndex)
        self:SetSelectedIndex(clickIndex) -- 这样设置一定不会是 -1 

        Events.Broadcast(Constants.EventNames.Player2DMainRefreshTitle, nil) -- 重绘 主场景 顶部页签 (的 "New" 标准) 

        local badgeId = self:GetSelectedBadgeId()
        local badgeData = self.badgeMap[badgeId]
        if badgeData.state == Player2DStates.BadgeState.Locked then 
            print(" 点击 Locked " .. tostring(badgeId) )

            -- tips 信息小窗口
            self:_DrawTipPopup( badgeId, node.gameObject, false )

        elseif badgeData.state == Player2DStates.BadgeState.UnShow then
            print(" 点击 UnShow " .. tostring(badgeId) )

            self:_DrawShowedBadge( index1Based, badgeId, self:GetRandomInitPos(150) )
            badgeData.state = Player2DStates.BadgeState.Showed
            badgeData.luaEnv:ShowFrame({ isShow = self:IsInEditMode(), isRed = badgeData.isCollect, isEdit = (self:GetSelectedBadgeId()==badgeId) })

            self:_DoShowedBadgesCollect()
            GameUtils.ReloadData(self.BadgeList, #self.badgeIdList) -- 重绘制 左侧徽章

        elseif badgeData.state == Player2DStates.BadgeState.Showed then
            print(" 点击 Showed " .. tostring(badgeId) )
            -- 将选中的 徽章 置顶: 
            self:_FloatUp2TopOrder( badgeData.transform )

        else
            printError("koko - state 值异常: " .. tostring(badgeData.state) )
        end
    end)
end


---@return UnityEngine.Vector2
function Player2DBadgePanel:GetRandomInitPos( radius_ )
    return Vector2(
        Random.Range( -radius_, radius_ ),
        Random.Range( -radius_, radius_ )
    )
end


-- 拖动 徽章 及其callbacks:
function Player2DBadgePanel:SetCanDrag()
    local isDragging = false
    local dragEventProxy = EventDragProxy.Create( self.BadgeShowRoot.gameObject )
    dragEventProxy.onPointerBeginDrag = function(eventData)
        if isNull(eventData) then return end
        if self:IsInEditMode() ~= true then return end
        local screenPos = eventData.position
        ---

        local badgeId = self:GetSelectedBadgeId()
        if badgeId <= 0 or self:IsShowedBadge(badgeId) == false then 
            print("koko - 没选中徽章")
            return
        end

        self.dragPos = screenPos

        self:PrepareMove()
        
        isDragging = true
    end

    dragEventProxy.onPointerDrag = function(eventData)
        if isNull(eventData) then return end
        if not isDragging then return end
        local screenPos = eventData.position

        local offset = screenPos - self.dragPos
        

        self.dragPos = screenPos

        print("drag - : " .. offset:ToString()  )
        self:MoveBadge( offset )

        ---
        self:_DoShowedBadgesCollect()
        -- 如果当前选中的徽章 无碰撞, 则要恢复它的 蓝框 
        do 
            local badgeId = self:GetSelectedBadgeId()
            local badgeData = self.badgeMap[badgeId]
            if badgeData.isCollect == false then 
                badgeData.luaEnv:ShowFrame({ isShow = self:IsInEditMode(), isRed = badgeData.isCollect, isEdit = (self:GetSelectedBadgeId()==badgeId) })
            end
        end

    end

    dragEventProxy.onPointerEndDrag = function(eventData)
        if isNull(eventData) then return end
        if not isDragging then return end

        print("drag - end "  )

        ---
        self:_DoShowedBadgesCollect()
        -- 如果当前选中的徽章 无碰撞, 则要恢复它的 蓝框 
        do 
            local badgeId = self:GetSelectedBadgeId()
            local badgeData = self.badgeMap[badgeId]
            if badgeData.isCollect == false then 
                badgeData.luaEnv:ShowFrame({ isShow = self:IsInEditMode(), isRed = badgeData.isCollect, isEdit = (self:GetSelectedBadgeId()==badgeId) })
            end
        end

        isDragging = false
    end
end



function Player2DBadgePanel:PrepareMove()
    local badgeId = self:GetSelectedBadgeId()
    local badgeData = self.badgeMap[badgeId]
    assert( badgeData.transform )
    badgeData.rawPos = badgeData.pos
end



function Player2DBadgePanel:MoveBadge( offset_ )
    local badgeId = self:GetSelectedBadgeId()
    local badgeData = self.badgeMap[badgeId]
    assert( badgeData.transform )

    local newPos = badgeData.transform.anchoredPosition + offset_
    newPos.x = Mathf.Clamp( newPos.x, DrawAreaBoundary.Left, DrawAreaBoundary.Right )
    newPos.y = Mathf.Clamp( newPos.y, DrawAreaBoundary.Bottom, DrawAreaBoundary.Top )

    badgeData.rawPos = newPos

    -- 尝试平滑
    --badgeData.pos = Vector2.MoveTowards( badgeData.pos, badgeData.rawPos, Time.deltaTime * 5000 )
    --badgeData.pos = Vector2.Lerp( badgeData.pos, badgeData.rawPos, Time.deltaTime * 25 )
    badgeData.pos = badgeData.rawPos

    ---
    badgeData.transform.anchoredPosition = badgeData.pos
end




function Player2DBadgePanel:_DrawTipPopup( badgeId, targetNode, isUpDown )

    ResourceModule.LoadGameObjectAsync("Prefabs/PlayerNew/Player2DTipPopup.prefab", function(go)
        if not KTool.IsNull(go) and not KTool.IsNull(targetNode) then
            go.name = "CommonTipsBoardBuff"
            local script = GetLuaBehaviour(go, "Game.UI.Player.Player2DBadgeTipPopup")
            if isNotNull(script) then

                ---@type GoodsVo
                local itemConf = self:GetBadgeConfById( badgeId )
                if not itemConf or next(itemConf) == nil then
                    printError("koko 异常")
                else

                    local itemData = self:GetBadgeDataById(badgeId)
                    -- 尚未拿到的 徽章 不显示时间
                    -- 别人的徽章 不显示时间
                    local timeInfo = (self:IsLockedBadge(badgeId) or self:IsShowMySelf()~=true  ) and "" or os.date("%Y.%m.%d", tonumber(itemData.createTime))

                    -- 界面关闭时的回调
                    script.Env:SetCloseCallBack(function()
                        if self.co_1 ~= nil then
                            cs_coroutine.stop(self.co_1)
                        end
                    end)

                    -- 正式绘制:
                    if self.co_1 ~= nil then
                        cs_coroutine.stop(self.co_1)
                    end
                    self.co_1 = cs_coroutine.start(function()
                        -- 
                        local isInTheCenter = true

                        -- 修正一次坐标位置
                        script.Env:FixBoardPosition(targetNode, isUpDown, isInTheCenter) -- !!! 此函数自己会等一帧才执行, 故下面的调用也需等待
                        coroutine.yield(Yielders.EndOfFrame)

                        -- 刷新提示板内容
                        script.Env:Fill( 
                            itemConf.name, 
                            itemConf.desc, 
                            itemConf.description, 
                            timeInfo,
                            itemConf.photoPath 
                        )

                        coroutine.yield(Yielders.EndOfFrame)
                        script.Env:Show()
                    end)                     
                end
            end
        end
    end, true, UIModule.RootCanvas.transform)


end


return Player2DBadgePanel
